c='p9';B='BÀI 13'
S=[]
S.append(TITLE('TIN HỌC 12 · BÀI 13','BÀI 13<br>KHÁI NIỆM, VAI TRÒ CỦA CSS','Mẫu định dạng CSS: cấu trúc, ba cách thiết lập, vai trò và lịch sử.',['CSS','Bộ chọn','CSS trong / ngoài / nội tuyến']))
S.append(goals(c,B,['Giải thích <b>CSS</b> và vai trò của mẫu định dạng.','Viết đúng <b>cấu trúc</b>: bộ chọn và vùng mô tả.','Phân biệt <b>CSS trong, ngoài, nội tuyến</b>.','Liên kết tệp CSS bằng <code>link</code> và <code>@import</code>.','Nêu <b>lợi ích</b> của CSS và <b>lịch sử</b> CSS.'],['Khái niệm mẫu định dạng CSS','Cấu trúc CSS','Ba cách thiết lập CSS','Vai trò, ý nghĩa, lịch sử','Trọng tâm, nâng cao, bài tập HSG']))
S.append(S2(c,B+' · 1','Vấn đề khi chưa có CSS',card('Định dạng thủ công bằng style',ul(['Mỗi phần tử phải đặt <b>thuộc tính style riêng</b>.','Nhiều trang, nhiều phần tử: <b>mất thời gian</b>.','Dễ <b>không thống nhất</b> giữa các trang.','Muốn đổi màu tiêu đề: sửa <b>từng thẻ</b>.'],6)),CODE('<h1 style="color:red">A</h1>\n<h1 style="color:red">B</h1>\n<h1 style="color:red">C</h1>',22)+KEY('Ba tiêu đề giống nhau mà viết <b>ba lần</b>. CSS ra đời để viết <b>một lần, dùng nhiều lần</b>.')))
S.append(CR(c,B+' · 1','Trang web có CSS (SGK Hình 13.2)',"<head>\n <style>\n  h1 {color: red;}\n  h1 {border: 2px solid blue;}\n  p {text-indent: 15px;}\n </style>\n</head>\n<body>\n <h1>Lịch sử phát triển HTML</h1>\n <p>Các chuẩn HTML …</p>\n <p>Ý tưởng ban đầu …</p>\n</body>",'<style>.x13 h1{color:red;border:2px solid blue;font-size:26px;margin:4px 0}.x13 p{text-indent:15px;font-family:Georgia,serif;font-size:21px;margin:4px 0}</style><div class="x13"><h1>Lịch sử phát triển HTML</h1><p>Các chuẩn HTML của trang web hiện nay được nhà vật lí Tim Berners-Lee đưa ra lần đầu…</p><p>Ý tưởng ban đầu của Berners-Lee là…</p></div>',KEY('Ba dòng trong <code>style</code> là ba <b>mẫu định dạng</b>. Mẫu 3 áp dụng cho <b>cả hai</b> thẻ <code>p</code>.'),19))
S.append(S2(c,B+' · 1','CSS là gì?',card('Cascading Style Sheets',ul(['<b>CSS</b> = tập hợp các <b>mẫu định dạng</b> viết <b>độc lập</b> với mã HTML.','CSS có <b>cách viết riêng</b> (ngôn ngữ CSS), <b>không phải HTML</b>.','Viết mẫu <b>một lần</b>, áp dụng đồng thời cho <b>mọi phần tử</b> được chọn.','Mẫu CSS có thể viết trên <b>nhiều hàng</b>.'],6)),KEY('CSS là định dạng <b>độc lập</b> với chuẩn HTML, dùng để thiết lập các mẫu định dạng của trang web.')+WARN('Nhầm “CSS là HTML”. HTML <b>đánh dấu nội dung</b>; CSS <b>định dạng cách hiển thị</b>.')))
S.append(S2(c,B+' · 2','Cấu trúc một mẫu CSS',CODE('h1 {\n  color: red;\n  text-align: center;\n}',24)+KEY('Mẫu CSS có <b>hai phần</b>: <b>bộ chọn</b> (selector) và <b>vùng mô tả</b> (declaration block).'),RES('<svg viewBox="0 0 520 270" style="width:100%"><rect x="10" y="20" width="110" height="60" rx="10" fill="#558B2F"/><text x="65" y="60" text-anchor="middle" font-size="26" font-weight="800" fill="#fff">h1</text><text x="65" y="108" text-anchor="middle" font-size="22" font-weight="800" fill="#558B2F">bộ chọn</text><rect x="130" y="20" width="380" height="150" rx="10" fill="#E8F5E9" stroke="#558B2F" stroke-width="4"/><text x="150" y="62" font-size="24" class="mono" fill="#0B2545">{ color: red;</text><text x="150" y="104" font-size="24" class="mono" fill="#0B2545">  text-align: center; }</text><text x="320" y="148" text-anchor="middle" font-size="22" font-weight="800" fill="#558B2F">vùng mô tả</text><rect x="140" y="190" width="170" height="44" rx="8" fill="#BF360C"/><text x="225" y="220" text-anchor="middle" font-size="22" font-weight="800" fill="#fff">thuộc tính</text><rect x="330" y="190" width="170" height="44" rx="8" fill="#1565C0"/><text x="415" y="220" text-anchor="middle" font-size="22" font-weight="800" fill="#fff">giá trị</text></svg>','Sơ đồ cấu trúc')))
S.append(TB(c,B+' · 2','Quy tắc viết mẫu CSS',['Quy tắc','Ví dụ'],[['Một quy định','<code>h1 {color: red;}</code>'],['Quy định = <b>thuộc tính : giá trị ;</b>','<code>text-indent: 15px;</code>'],['Nhiều quy định: ngăn bằng <b>dấu ;</b>','<code>p {text-indent: 15px; color: blue;}</code>'],['Nhiều bộ chọn: ngăn bằng <b>dấu phẩy</b>','<code>h1, h2, h3 {color: red;}</code>'],['Chú thích','<code>/* nội dung chú thích */</code>']],note=WARN('Giữa tên thuộc tính và giá trị dùng <b>dấu hai chấm :</b>; cuối mỗi quy định có <b>dấu chấm phẩy ;</b>.')))
S.append(CR(c,B+' · 2','Ví dụ 1, 2, 3 của SGK',"h1 {color: red;}\n\np {text-indent: 15px;\n   color: blue;}\n\nh1, h2, h3 {color: red;}",'<div style="font-family:Georgia,serif;font-size:23px"><b style="color:red">VD1:</b> mọi <b>h1</b> có chữ đỏ.<br><br><b style="color:red">VD2:</b> mọi <b>p</b> thụt dòng đầu 15px và chữ xanh dương.<br><br><b style="color:red">VD3:</b> <b>h1, h2, h3</b> cùng chữ đỏ (bộ chọn nhiều thẻ).</div>',KEY('Bộ chọn có thể là <b>một thẻ</b> hoặc <b>nhiều thẻ</b> ngăn bằng dấu phẩy.'),22))
S.append(TB(c,B+' · 2','Ba cách thiết lập CSS',['Cách','Viết ở đâu','Phạm vi'],[['CSS <b>trong</b> (internal)','thẻ <code>style</code> trong <code>head</code>','<b>chỉ tệp HTML đó</b>'],['CSS <b>ngoài</b> (external)','tệp <code>.css</code> riêng, nối bằng <code>link</code> hoặc <code>@import</code>','<b>nhiều trang</b>, cả website'],['CSS <b>nội tuyến</b> (inline)','thuộc tính <code>style</code> trong thẻ','<b>một phần tử</b>']],note=KEY('Chọn theo phạm vi: một phần tử → nội tuyến; một trang → trong; nhiều trang → ngoài.')))
S.append(CR(c,B+' · 2','CSS trong (internal CSS)',"<head>\n  <style>\n    h1 {color: red;}\n    p {color: blue;}\n  </style>\n</head>",'<div style="font-family:Georgia,serif;font-size:23px">Đặt toàn bộ mẫu trong thẻ <b style="color:#000">style</b>, nằm trong phần tử <b style="color:#000">head</b>.<br><br>Chỉ áp dụng cho <b style="color:#000">tệp HTML hiện thời</b>.</div>',WARN('Thẻ <code>style</code> đặt trong <code>body</code> hoặc ngoài <code>head</code> là chưa đúng chuẩn SGK.'),22))
S.append(CR(c,B+' · 2','CSS ngoài (external CSS)',"/* tệp styles.css */\nh1 {color: red;}\np {text-indent: 15px;}\n\n<!-- trong tệp HTML -->\n<head>\n <link href=\"styles.css\"\n  rel=\"stylesheet\"\n  type=\"text/css\">\n</head>",'<div style="font-family:Georgia,serif;font-size:23px"><b style="color:#000">Bước 1:</b> viết mẫu trong tệp <b style="color:#000">.css</b>.<br><b style="color:#000">Bước 2:</b> nối vào trang bằng thẻ <b style="color:#000">link</b> đặt trong <b style="color:#000">head</b>.<br><br>Tệp CSS <b style="color:#000">không chứa thẻ HTML</b>.</div>',KEY('<code>href</code> là đường dẫn tới tệp CSS; <code>rel="stylesheet"</code> cho biết đó là tệp định dạng.'),19))
S.append(CR(c,B+' · 2','Cách 2: lệnh @import',"<head>\n  <style>\n    @import \"styles.css\";\n  </style>\n</head>",'<div style="font-family:Georgia,serif;font-size:23px">Cách 2 nối tệp CSS: lệnh <b style="color:#000">@import</b> đặt trong thẻ <b style="color:#000">style</b> ở phần <b style="color:#000">head</b>.</div>',OK('Cách 1: <code>link</code>. Cách 2: <code>@import</code>. Cả hai đều nối <b>tệp CSS ngoài</b> vào trang.')+KEY('Một tệp CSS có thể dùng cho <b>nhiều trang web</b>: sửa một lần, mọi trang đổi theo.'),22))
S.append(CR(c,B+' · 2','CSS nội tuyến (inline CSS)','<p style="color: blue;\n   text-indent: 15px">\n  Đoạn này chỉ định dạng\n  riêng cho thẻ p này.\n</p>','<p style="color:blue;text-indent:15px;font-family:Georgia,serif;font-size:23px;margin:0">Đoạn này chỉ định dạng riêng cho thẻ p này.</p>',WARN('CSS nội tuyến làm <b>mất thời gian</b> khi có nhiều phần tử và khó đồng bộ. Chỉ dùng cho <b>trường hợp riêng lẻ</b>.'),22))
S.append(PT(c,B+' · 3','Vai trò và ý nghĩa của CSS','Lợi ích',['<b>Tách</b> việc nhập nội dung (HTML) và việc định dạng (CSS).','Viết mẫu <b>một lần</b>, dùng <b>nhiều lần</b>.','Định dạng cho <b>nhiều trang, cả website</b> bằng một tệp CSS.','Đổi định dạng: sửa <b>một lần</b>.','Định dạng <b>thống nhất</b>, chuyên nghiệp.'],KEY('Nếu không dùng CSS, phải đặt thuộc tính cho <b>từng phần tử</b>: tốn thời gian và không thống nhất.')))
S.append(S2(c,B+' · 3','Một tệp CSS, nhiều trang HTML',RES('<svg viewBox="0 0 520 330" style="width:100%"><rect x="170" y="10" width="180" height="60" rx="10" fill="#558B2F"/><text x="260" y="48" text-anchor="middle" font-size="24" font-weight="800" fill="#fff">styles.css</text><rect x="10" y="230" width="150" height="60" rx="10" fill="#1565C0"/><text x="85" y="268" text-anchor="middle" font-size="22" font-weight="800" fill="#fff">index.html</text><rect x="185" y="230" width="150" height="60" rx="10" fill="#1565C0"/><text x="260" y="268" text-anchor="middle" font-size="22" font-weight="800" fill="#fff">thethao.html</text><rect x="360" y="230" width="150" height="60" rx="10" fill="#1565C0"/><text x="435" y="268" text-anchor="middle" font-size="22" font-weight="800" fill="#fff">nghethuat.html</text><path d="M240 72 L100 228 M260 72 L260 228 M280 72 L420 228" stroke="#0B2545" stroke-width="4"/><text x="260" y="170" font-size="22" font-weight="800" fill="#C62828" text-anchor="middle">link href="styles.css"</text></svg>','Sơ đồ'),card('Ý nghĩa',ul(['Ba trang cùng <b>link</b> tới một tệp.','Đổi màu tiêu đề trong tệp CSS: <b>cả ba trang đổi</b>.','Website có <b>phong cách thống nhất</b>.'],6))))
S.append(TB(c,B+' · 3','Lịch sử CSS (đọc thêm)',['Mốc','Sự kiện'],[['1994','Ý tưởng của kĩ sư <b>Håkon Wium Lie</b> (Na Uy), làm việc với Tim Berners-Lee tại CERN'],['1996','<b>CSS1</b> chính thức ra đời'],['1998','<b>CSS2</b> hoàn thiện'],['2011','<b>CSS2.1</b>; bản nâng cấp hoàn thiện năm 2016'],['Từ CSS3','phát triển theo <b>từng gói riêng</b>; CSS4, CSS5 vẫn đang được thiết lập']],note=OK('Tổ chức phát triển chuẩn HTML, CSS: <b>W3C</b> (World Wide Web Consortium), website <code>www.w3.org</code>.')))
S.append(S2(c,'TRỌNG TÂM','Những điều phải nhớ',card('Ghi nhớ',ul(['CSS <b>không phải HTML</b>: ngôn ngữ riêng để định dạng.','Mẫu = <b>bộ chọn { thuộc tính: giá trị; }</b>.','Ba cách: <b>trong</b> (style trong head), <b>ngoài</b> (tệp .css + link/@import), <b>nội tuyến</b> (thuộc tính style).','Lợi ích: <b>viết một lần, dùng nhiều lần</b>; một tệp cho cả website.'],6)),T(tr('Muốn…','Dùng',h=True)+tr('Cả trang','CSS trong',m=True)+tr('Nhiều trang','CSS ngoài',m=True)+tr('Một thẻ','CSS nội tuyến',m=True))+WARN('<code>link</code> đặt trong <b>head</b>; chú thích CSS là <code>/* */</code>, không phải <code>&lt;!-- --&gt;</code>.')))
S.append(S2(c,'NÂNG CAO','Điều dễ nhầm về CSS',card('Bẫy',ul(['Chú thích CSS là <code>/* … */</code>; <code>&lt;!-- --&gt;</code> là của HTML.','Quên <b>dấu ;</b> giữa hai quy định thì quy định sau có thể <b>mất tác dụng</b>.','Sai tên thuộc tính: trình duyệt <b>bỏ qua</b> quy định đó, không báo lỗi.','Đường dẫn <code>href</code> của <code>link</code> theo quy tắc <b>đường dẫn tương đối</b> (Bài 10).'],6)),card('So sánh nhanh',ul(['<b>Trong</b>: không cần tệp riêng, chỉ một trang.','<b>Ngoài</b>: tải được một lần, dùng lại cho nhiều trang.','<b>Nội tuyến</b>: ưu tiên cao hơn khi trùng (Bài 17).'],6))))
tap=[('Ngôn ngữ CSS chính là HTML. Đúng hay sai?',),('Chỉ cần sửa một tệp CSS có thể đổi định dạng của nhiều trang, thậm chí cả website. Đúng hay sai?',),('Muốn tất cả đoạn p của trang chữ xanh (blue), viết mẫu CSS thế nào?',),('Giải thích ý nghĩa: <code>h1,h2,h3 {border: 2px solid red;}</code>',),('Muốn áp dụng CSS cho nhiều trang cùng lúc thì làm thế nào?',)]
tapa=[('<b>Sai</b>: CSS có cách viết riêng, độc lập với HTML.',),('<b>Đúng</b>: dùng CSS ngoài, các trang cùng liên kết tới tệp.',),('<code>p {color: blue;}</code>',),('Các thẻ <b>h1, h2, h3</b> đều có khung viền <b>dày 2px, nét liền, màu đỏ</b>.',),('Dùng <b>CSS ngoài</b>: viết tệp .css, rồi nối bằng <code>link</code> (hoặc <code>@import</code>) trong từng trang.',)]
S+=qslides(c,B+' · TẬP','Bài tập củng cố',tap,per=5)+qslides(c,B+' · ĐÁP ÁN','Đáp án chi tiết',tapa,ans=True,per=5)
hq=[('Mẫu CSS sau nằm trong tệp <code>style.css</code>. Tìm 2 lỗi:',"<style>\n h1 {color = red; text-align: center}\n p {font-size: 20px color: blue;}\n</style>"),
 ('Cho tệp HTML: <code>&lt;link href="css/main.css" rel="stylesheet"&gt;</code> đặt trong <code>head</code> của trang ở thư mục gốc. Tệp CSS đặt ở đâu?',),
 ('Đúng hay sai: (a) Thẻ <code>style</code> nằm trong <code>head</code>. (b) Tệp .css chứa cả thẻ <code>&lt;html&gt;</code>. (c) Chú thích CSS viết <code>&lt;!-- --&gt;</code>. (d) <code>@import</code> cũng nối được tệp CSS ngoài.',),
 ('Website có 10 trang cần đổi màu tiêu đề từ đỏ sang xanh. So sánh số chỗ phải sửa nếu dùng CSS ngoài và CSS nội tuyến (mỗi trang 3 tiêu đề).',),
 ('Viết mã CSS ngoài: tiêu đề h1 màu đỏ, p chữ xanh thụt dòng 2em; viết cả thẻ liên kết.',),
 ('Mẫu <code>h1 {color: red;}</code> và <code>h1 {border: 2px solid blue;}</code> viết liên tiếp có cần gộp không? Gộp thế nào?',)]
ha=[('(1) <code>color = red</code> phải là <code>color: red</code>. (2) thiếu <b>dấu ;</b> sau <code>20px</code>. (Và thẻ <code>style</code> không có trong tệp .css.)',),
 ('Trong thư mục con <b>css</b> của thư mục chứa trang: <code>css/main.css</code> (đường dẫn tương đối).',),
 ('(a) <b>Đúng</b>. (b) <b>Sai</b>. (c) <b>Sai</b>: dùng <code>/* */</code>. (d) <b>Đúng</b>.',),
 ('CSS ngoài: <b>1 chỗ</b>. CSS nội tuyến: 10 × 3 = <b>30 chỗ</b>.',),
 ('<code>h1 {color: red;} p {color: blue; text-indent: 2em;}</code> và <code>&lt;link href="style.css" rel="stylesheet"&gt;</code> trong head.',),
 ('Không bắt buộc, kết quả như nhau. Gộp: <code>h1 {color: red; border: 2px solid blue;}</code>.',)]
S+=qslides(c,B+' · HSG','Bài tập luyện HSG',hq,per=3,fs=19)+qslides(c,B+' · HSG · ĐÁP ÁN','Đáp án chi tiết',ha,ans=True,per=3,fs=19)
mkdeck('w3-b13.html','Bài 13 · Khái niệm, vai trò của CSS',S)
